// src/app/page.tsx
"use client";

import Image from "next/image";
import Link from "next/link";
import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";

export default function HomePage() {
  const router = useRouter();
  const [place, setPlace] = useState("");

  const trimmed = useMemo(() => place.trim(), [place]);
  const canSearch = trimmed.length > 0;

  function onSearch() {
    if (!canSearch) return;
    router.push(`/results?place=${encodeURIComponent(trimmed)}`);
  }

  function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    onSearch();
  }

  return (
    <main className="mx-auto w-full max-w-md px-4 py-10">
      <header className="flex items-center gap-3">
        <div className="relative h-9 w-9 overflow-hidden rounded-xl">
          <Image src="/image.png" alt="Hanami Check" fill className="object-cover" priority />
        </div>
        <h1 className="text-2xl font-semibold text-neutral-900">Hanami Check</h1>
      </header>

      <p className="mt-2 pl-1 text-sm text-neutral-600">
        いま行くべき花見スポットを、投稿ベースで判断。
      </p>

      {/* 「いま行くべき〜」と「場所を検索」の間：適度に（必要ならここで調整） */}
      <p className="mt-7 text-sm font-semibold text-neutral-900">場所を検索</p>

      {/* 「場所を検索」と検索窓の間：狭め */}
      <form onSubmit={onSubmit} className="mt-2">
        <input
          value={place}
          onChange={(e) => setPlace(e.target.value)}
          placeholder="例：上野公園 / 東京駅"
          className="w-full rounded-xl border border-neutral-200 px-4 py-3 text-sm focus:border-neutral-400 focus:outline-none"
        />

        {/* ボタンは縦並び */}
        <div className="mt-4 space-y-3">
          <button
            type="submit"
            disabled={!canSearch}
            className="inline-flex w-full items-center justify-center rounded-xl bg-neutral-900 px-4 py-3 text-sm font-semibold text-white shadow-sm hover:bg-neutral-800 disabled:cursor-not-allowed disabled:opacity-50"
          >
            検索する
          </button>

          <Link
            href="/post"
            className="inline-flex w-full items-center justify-center rounded-xl border border-neutral-200 bg-white px-4 py-3 text-sm font-semibold text-neutral-900 shadow-sm hover:bg-neutral-50"
          >
            開花状況を投稿する
          </Link>

          <Link
            href="/contact"
            className="inline-flex w-full items-center justify-center rounded-xl border border-neutral-200 bg-white px-4 py-3 text-sm font-semibold text-neutral-900 shadow-sm hover:bg-neutral-50"
          >
            お問い合わせ
          </Link>
        </div>

        {!canSearch ? (
          <p className="mt-3 text-xs text-neutral-500">場所を入力してから検索してください</p>
        ) : null}
      </form>
    </main>
  );
}